insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','The reward of deeds depends upon the intentions and every person will get the reward according to what he has intended.','Sahih al-Bukhari 1',true,'sunnah.com check 2026-10-23',1000 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 1' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','A Muslim is the one who avoids harming Muslims with his tongue and hands.','Sahih al-Bukhari 10',true,'sunnah.com check 2026-10-23',1001 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 10' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','None of you will have faith till he wishes for his (Muslim) brother what he likes for himself.','Sahih al-Bukhari 13',true,'sunnah.com check 2026-10-23',1002 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 13' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','Facilitate things to people (concerning religious matters), and do not make it hard for them and give them good tidings and do not make them run away (from Islam).','Sahih al-Bukhari 69',true,'sunnah.com check 2026-10-23',1003 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 69' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','The strong is not the one who overcomes the people by his strength, but the strong is the one who controls himself while in anger.','Sahih al-Bukhari 6114',true,'sunnah.com check 2026-10-23',1004 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 6114' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','Anybody who believes in Allah and the Last Day should talk what is good or keep quiet.','Sahih al-Bukhari 6018',true,'sunnah.com check 2026-10-23',1005 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 6018' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','A man asked the Prophet ﷺ for advice. He said, “Do not become angry,” and gave the same answer each time the man asked again.','Sahih al-Bukhari 6116',true,'sunnah.com check 2026-10-23',1006 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 6116' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','The Prophet ﷺ was asked which deeds are loved most by Allah. He said, “The most regular constant deeds even though they may be few.”','Sahih al-Bukhari 6465',true,'sunnah.com check 2026-10-23',1007 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 6465' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','The best among you (Muslims) are those who learn the Qur''an and teach it.','Sahih al-Bukhari 5027',true,'sunnah.com check 2026-10-23',1008 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 5027' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','(Saying) a good word is also Sadaqa (charity).','Sahih al-Bukhari 2989',true,'sunnah.com check 2026-10-23',1009 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 2989' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','Al-Wasil is not the one who recompenses the good done to him by his relatives, but Al-Wasil is the one who keeps good relations with those relatives who had severed the bond of kinship with him.','Sahih al-Bukhari 5991',true,'sunnah.com check 2026-10-23',1010 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 5991' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','Whoever is not grateful to the people, he is not grateful to Allah.','Jami'' at-Tirmidhi 1954 (sahih)',true,'sunnah.com check 2026-10-23',1011 where not exists (select 1 from public.daily_items where reference = 'Jami'' at-Tirmidhi 1954 (sahih)' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','Verily Allah does not look to your faces and your wealth but He looks to your heart and to your deeds.','Sahih Muslim 2564c',true,'sunnah.com check 2026-10-23',1012 where not exists (select 1 from public.daily_items where reference = 'Sahih Muslim 2564c' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'hadith','He who has in his heart the weight of a mustard seed of pride shall not enter Paradise.','Sahih Muslim 91a',true,'sunnah.com check 2026-10-23',1013 where not exists (select 1 from public.daily_items where reference = 'Sahih Muslim 91a' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'sunnah','Feed the hungry, visit the sick, and set free the captives.','Sahih al-Bukhari 5649',true,'sunnah.com check 2026-10-23',1014 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 5649' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'sunnah','Asked which deeds in Islam are best, the Prophet ﷺ said: “To feed (the poor) and greet those whom you know and those whom you do not know.”','Sahih al-Bukhari 12',true,'sunnah.com check 2026-10-23',1015 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 12' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'sunnah','Save yourself from Hell-fire even by giving half a date-fruit in charity.','Sahih al-Bukhari 1417',true,'sunnah.com check 2026-10-23',1016 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 1417' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'sunnah','By Allah! I ask for forgiveness from Allah and turn to Him in repentance more than seventy times a day.','Sahih al-Bukhari 6307',true,'sunnah.com check 2026-10-23',1017 where not exists (select 1 from public.daily_items where reference = 'Sahih al-Bukhari 6307' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'sunnah','Don''t consider anything insignificant out of good things even if it is that you meet your brother with a cheerful countenance.','Sahih Muslim 2626',true,'sunnah.com check 2026-10-23',1018 where not exists (select 1 from public.daily_items where reference = 'Sahih Muslim 2626' and verified);
insert into public.daily_items (kind,text,reference,verified,verified_by,sort) select 'sunnah','The two rak''ahs at dawn are better than this world and what it contains.','Sahih Muslim 725a',true,'sunnah.com check 2026-10-23',1019 where not exists (select 1 from public.daily_items where reference = 'Sahih Muslim 725a' and verified);
